dashboard.definition:
{
  "title": "Facilitator Board",
  "description": "Live booth view (1920x3600) — active teams, leaderboard, act funnel, trap log, hint distribution, v2.9 booth-wide discovery analytics, v2.10 Adaptive Hans telemetry, v2.10 facilitator phone-call cinematics, v2.10 investigation-board analytics, v2.11 Floor-30 hub analytics, v2.12 Phase 7 Tier 1 ending-branch distribution, v2.13 booth-kiosk operations + post-session feedback + abandonment funnel, and v2.14 operator activity (facilitator action verb mix + audio mix tweaks). Drilldown opens per-team timeline.",
  "dataSources": {
    "ds_active_teams": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | stats latest(event_type) as last_event, latest(act) as act, latest(score) as score, latest(completed_tasks) as done, latest(total_tasks) as total, latest(wrong_count) as wrongs, latest(hints_used) as hints, latest(difficulty) as difficulty, latest(mode) as mode, max(_time) as last_ts by team_code | eval idle_seconds=round(now()-last_ts), state=case(last_event=\"session_end\",\"COMPLETE\", idle_seconds>180,\"STALLED\", idle_seconds>60,\"SLOW\", 1=1,\"ACTIVE\"), progress=tostring(coalesce(done,0)).\"/\".tostring(coalesce(total,26)) | sort -score | table team_code, state, act, progress, score, wrongs, hints, difficulty, mode, idle_seconds",
        "queryParameters": {"earliest": "-1h@m", "latest": "now"}
      }
    },
    "ds_leaderboard": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=session_end outcome=victory | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | dedup team_code sortby -_time | sort -score_scaled | head 10 | streamstats count as rank | eval time=tostring(elapsed_seconds, \"duration\") | table rank, team_code, score_scaled, time, difficulty",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_act_funnel": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=act_start | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | stats dc(team_code) as teams_reached by act | sort act | eval act_label=case(act=1,\"1: Christmas Party\", act=2,\"2: The Takeover\", act=3,\"3: The Vault\", act=4,\"4: Counterattack\", act=5,\"5: The Escape\", 1=1,\"Act \".act) | table act_label, teams_reached",
        "queryParameters": {"earliest": "-4h@h", "latest": "now"}
      }
    },
    "ds_trap_log": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=trap_hit | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | sort -_time | head 25 | eval ts=strftime(_time,\"%H:%M:%S\") | table ts, team_code, act, task_id, trap_code, difficulty",
        "queryParameters": {"earliest": "-4h@h", "latest": "now"}
      }
    },
    "ds_hint_distribution": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=hint_used | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | stats count as hint_count by hint_level | sort hint_level | eval level_label=case(hint_level=1,\"1 (Free)\", hint_level=2,\"2 (-50)\", hint_level=3,\"3 (-150)\", hint_level=4,\"4 (Answer)\", 1=1,\"Lvl \".hint_level) | table level_label, hint_count",
        "queryParameters": {"earliest": "-4h@h", "latest": "now"}
      }
    },
    "ds_outcome_dist": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=session_end | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | eval outcome=upper(coalesce(outcome,\"unknown\")) | stats count by outcome",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_kpi_active": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | stats latest(event_type) as last_ev by team_code | search NOT last_ev=session_end | stats count as active_teams",
        "queryParameters": {"earliest": "-15m", "latest": "now"}
      }
    },
    "ds_kpi_completed_today": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=session_end outcome=victory | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | dedup team_code sortby -_time | stats count as completed_today",
        "queryParameters": {"earliest": "@d", "latest": "now"}
      }
    },
    "ds_kpi_failed_today": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=session_end outcome=loss | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | dedup team_code sortby -_time | stats count as failed_today",
        "queryParameters": {"earliest": "@d", "latest": "now"}
      }
    },
    "ds_kpi_avg_time": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=session_end outcome=victory | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | dedup team_code sortby -_time | stats avg(elapsed_seconds) as avg_sec | eval avg_time=tostring(round(avg_sec), \"duration\")",
        "queryParameters": {"earliest": "@d", "latest": "now"}
      }
    },
    "ds_side_story_discovery": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event (event_type=side_story_discovered OR event_type=session_start) | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | eventstats dc(eval(if(event_type=\"session_start\", team_code, null()))) as total_teams | where event_type=\"side_story_discovered\" | stats dc(team_code) as teams_found, max(total_teams) as total_teams by story_id, story_title | eval pct=if(total_teams>0, round(teams_found/total_teams*100, 0), 0) | eval booth_share=pct.\"%\" | sort -teams_found | head 10 | rename story_title as side_story, teams_found as teams | table side_story, teams, booth_share",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_egg_discovery": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event (event_type=easter_egg_found OR event_type=session_start) | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | eventstats dc(eval(if(event_type=\"session_start\", team_code, null()))) as total_teams | where event_type=\"easter_egg_found\" | stats dc(team_code) as teams_found, max(total_teams) as total_teams by egg_id, egg_title, trigger | eval pct=if(total_teams>0, round(teams_found/total_teams*100, 0), 0) | eval booth_share=pct.\"%\" | eval discovery=case(trigger=\"konami\", \"Konami code\", trigger=\"keypad\", \"keypad (6xxx)\", 1=1, trigger) | sort -teams_found | head 10 | rename egg_title as easter_egg, teams_found as teams | table easter_egg, teams, booth_share, discovery",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_discovery_top_teams": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event (event_type=side_story_discovered OR event_type=easter_egg_found) | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | stats dc(story_id) as stories, dc(egg_id) as eggs by team_code | eval stories=coalesce(stories,0), eggs=coalesce(eggs,0), total_discoveries=stories+eggs | sort -total_discoveries -stories -eggs | head 10 | streamstats count as rank | table rank, team_code, stories, eggs, total_discoveries",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_hans_recent": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=hans_reaction | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | sort -_time | head 25 | eval ts=strftime(_time,\"%H:%M:%S\"), trigger_label=case(trigger=\"idle\",\"Idle (2m quiet)\", trigger=\"lazy_queries\",\"Broad SPL\", trigger=\"keypad_spam\",\"Keypad spam\", trigger=\"fast_solves\",\"Fast solves\", trigger=\"side_story_discoveries\",\"Side story\", trigger=\"konami_code\",\"Konami\", 1=1, trigger) | table ts, team_code, act, trigger_label, tone, reaction_id",
        "queryParameters": {"earliest": "-4h@h", "latest": "now"}
      }
    },
    "ds_hans_mix": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=hans_reaction | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | stats count by trigger, tone | eval trigger_label=case(trigger=\"idle\",\"Idle\", trigger=\"lazy_queries\",\"Lazy SPL\", trigger=\"keypad_spam\",\"Keypad\", trigger=\"fast_solves\",\"Fast\", trigger=\"side_story_discoveries\",\"Side\", trigger=\"konami_code\",\"Konami\", 1=1, trigger) | sort -count | table trigger_label, tone, count",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_kpi_hans_today": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=hans_reaction | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | stats count as hans_today",
        "queryParameters": {"earliest": "@d", "latest": "now"}
      }
    },
    "ds_phone_recent": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event (event_type=phone_call_incoming OR event_type=phone_call_answered OR event_type=phone_call_missed) | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | sort -_time | head 25 | eval ts=strftime(_time,\"%H:%M:%S\"), state=case(event_type=\"phone_call_incoming\",\"INCOMING\", event_type=\"phone_call_answered\",\"ANSWERED\", event_type=\"phone_call_missed\",\"MISSED\", 1=1, event_type), caller_label=case(caller=\"powell\",\"Sgt. Powell\", caller=\"hans\",\"Hans Gruber\", caller=\"holly\",\"Holly Gennero\", 1=1, caller) | table ts, team_code, state, caller_label, delivery_type, line_preset_id",
        "queryParameters": {"earliest": "-4h@h", "latest": "now"}
      }
    },
    "ds_phone_mix": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=phone_call_incoming | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | stats count by caller, delivery_type | eval caller_label=case(caller=\"powell\",\"Powell\", caller=\"hans\",\"Hans\", caller=\"holly\",\"Holly\", 1=1, caller) | sort -count | table caller_label, delivery_type, count",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_kpi_phone_today": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=phone_call_incoming | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | stats count as phone_today",
        "queryParameters": {"earliest": "@d", "latest": "now"}
      }
    },
    "ds_kpi_board_pins_today": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=clue_pinned | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | stats count as board_pins_today",
        "queryParameters": {"earliest": "@d", "latest": "now"}
      }
    },
    "ds_board_pin_mix": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=clue_pinned | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | eval pin_type=coalesce(pin_type, \"unknown\"), pin_label=case(pin_type=\"task\",\"Task\", pin_type=\"story\",\"Side Story\", pin_type=\"intercept\",\"Intercept\", pin_type=\"egg\",\"Easter Egg\", pin_type=\"lore\",\"Lore\", pin_type=\"suspect\",\"Suspect\", 1=1, pin_type) | stats count by pin_label, source | sort -count | head 30 | table pin_label, source, count",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_board_top_teams": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event (event_type=clue_pinned OR event_type=thread_drawn OR event_type=note_added OR event_type=board_exported) | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | stats count(eval(event_type=\"clue_pinned\")) as pins, count(eval(event_type=\"thread_drawn\")) as threads, count(eval(event_type=\"note_added\")) as notes, count(eval(event_type=\"board_exported\")) as exports by team_code | eval detective_score=pins + (threads * 2) + notes + (exports * 5) | where detective_score > 0 | sort -detective_score | head 10 | streamstats count as rank | table rank, team_code, pins, threads, notes, exports, detective_score",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_kpi_hub_sessions_today": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=hub_opened | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | stats dc(team_code) as hub_teams_today",
        "queryParameters": {"earliest": "@d", "latest": "now"}
      }
    },
    "ds_hub_station_mix": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=hub_station_clicked | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | eval station_id=coalesce(station_id,\"unknown\"), availability=coalesce(availability,\"unknown\"), station_label=case(station_id=\"terminal\",\"SPL Terminal\", station_id=\"keypad\",\"Vault Keypad\", station_id=\"leads\",\"Leads\", station_id=\"briefing\",\"Briefing Wall\", station_id=\"blueprint\",\"Blueprint\", station_id=\"comms\",\"Comms\", station_id=\"board\",\"Investigation\", 1=1, station_id) | stats count by station_label, availability | sort -count | head 30 | table station_label, availability, count",
        "queryParameters": {"earliest": "-4h@h", "latest": "now"}
      }
    },
    "ds_hub_dwell": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=hub_closed | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") elapsed_ms>0 | eval elapsed_s=round(elapsed_ms/1000, 1), trigger=coalesce(trigger,\"unknown\") | stats count, median(elapsed_s) as median_dwell_s, max(elapsed_s) as max_dwell_s by trigger | sort -count | table trigger, count, median_dwell_s, max_dwell_s",
        "queryParameters": {"earliest": "-4h@h", "latest": "now"}
      }
    },
    "ds_kpi_endings_today": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=ending_classified | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | stats count as endings_today",
        "queryParameters": {"earliest": "@d", "latest": "now"}
      }
    },
    "ds_ending_distribution": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=ending_classified | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | eval ending_id=lower(coalesce(ending_id,\"unknown\")), ending_label=case(ending_id=\"analyst\",\"Analyst (clean + curious)\", ending_id=\"cowboy\",\"Cowboy (messy but wins)\", ending_id=\"speedrunner\",\"Speedrunner (< 50% timer)\", ending_id=\"default\",\"Default (vault opens)\", 1=1, \"Unknown\"), difficulty=coalesce(difficulty,\"unknown\") | stats count by ending_label, difficulty | sort ending_label difficulty | table ending_label, difficulty, count",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_ending_recent": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=ending_classified | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | sort -_time | head 20 | eval ts=strftime(_time,\"%H:%M:%S\"), elapsed=tostring(elapsed_seconds, \"duration\"), ending_id=lower(coalesce(ending_id,\"unknown\")) | table ts, team_code, ending_id, elapsed, wrong_count, hint_tokens_spent, side_stories_discovered, difficulty",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_kpi_kiosk_today": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=kiosk_activated | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | eval kiosk_mode=lower(coalesce(kiosk_mode,\"gameplay\")) | stats dc(team_code) as kiosk_sessions",
        "queryParameters": {"earliest": "@d", "latest": "now"}
      }
    },
    "ds_kiosk_reset_mix": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=kiosk_idle_reset | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | eval reason=lower(coalesce(kiosk_reason,\"timeout\")) | stats count by reason | sort -count",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_kiosk_recent": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event (event_type=kiosk_idle_reset OR event_type=kiosk_watchdog_reload) | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | sort -_time | head 20 | eval ts=strftime(_time,\"%H:%M:%S\"), uptime=if(isnum(uptime_ms),tostring(round(uptime_ms/1000,0),\"duration\"),\"-\"), reason=coalesce(kiosk_reason,\"-\") | table ts, team_code, event_type, uptime, reason",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_kpi_feedback_avg": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=session_feedback | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | eval r=tonumber(rating) | where r>0 | stats avg(r) as avg_rating | eval avg_rating=round(avg_rating,2)",
        "queryParameters": {"earliest": "@d", "latest": "now"}
      }
    },
    "ds_feedback_distribution": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=session_feedback | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | eval r=tonumber(rating), bucket=case(r=1,\"1 star\",r=2,\"2 stars\",r=3,\"3 stars\",r=4,\"4 stars\",r=5,\"5 stars\",skipped=\"true\",\"Skipped\",1=1,\"Skipped\") | stats count by bucket | sort bucket",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_abandon_by_act": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=session_abandoned | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | eval a=tonumber(exit_act), act_label=case(a=0,\"Act 1\",a=1,\"Act 2\",a=2,\"Act 3\",a=3,\"Act 4\",a=4,\"Act 5\",1=1,\"Unknown\") | stats count by act_label | sort act_label",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_kpi_operator_today": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=facilitator_action | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | stats count as facilitator_clicks",
        "queryParameters": {"earliest": "@d", "latest": "now"}
      }
    },
    "ds_facilitator_action_mix": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=facilitator_action | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | eval verb=lower(coalesce(fac_action,\"unknown\")) | stats count by verb | sort -count",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_audio_setting_mix": {
      "type": "ds.search",
      "options": {
        "query": "index=nakatomi_sessions sourcetype=nakatomi:session:event event_type=audio_setting_changed | where (\"$booth_token$\"=\"\" OR booth_id=\"$booth_token$\") | eval setting=coalesce(audio_setting,\"unknown\") | stats count by setting | sort -count",
        "queryParameters": {"earliest": "-24h@h", "latest": "now"}
      }
    },
    "ds_setup": {
      "type": "ds.test",
      "options": {
        "data": {
          "fields": [
            {"name": "STEP", "type": "string"},
            {"name": "INSTRUCTION", "type": "string"}
          ],
          "columns": [
            ["1", "2", "3", "4"],
            [
              "Confirm telemetry: open game.html → mode-select pill should read 'Telemetry: ... booth=<id>'",
              "Filter to one booth via 'Booth ID' input (top-right). Leave blank for all booths.",
              "Click any team_code row in 'Active Teams' to drill into a per-team timeline (planned for next iteration)",
              "Treat 'STALLED' (>3 min idle) as a cue to walk over to the booth and offer help"
            ]
          ]
        }
      }
    }
  },
  "visualizations": {
    "viz_header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "```\n> NAKATOMI HEIST  ·  FACILITATOR BOARD  ·  v2.10.0\n> LIVE BOOTH OVERVIEW  ·  AUTO-REFRESH 15s  ·  EXPECT ~10s LAG FROM HEC\n> SCROLL FOR DISCOVERY ANALYTICS + ADAPTIVE HANS LOG →\n> ────────────────────────────────────────────────────────────────────────────\n```",
        "fontColor": "#33ff33",
        "backgroundColor": "#000d00"
      }
    },
    "viz_kpi_active": {
      "type": "splunk.singlevalue",
      "title": "Active Teams (last 15 min)",
      "dataSources": {"primary": "ds_kpi_active"},
      "options": {
        "majorColor": "#33ff33",
        "backgroundColor": "#000d00",
        "trendDisplay": "off"
      }
    },
    "viz_kpi_completed": {
      "type": "splunk.singlevalue",
      "title": "Completed Today",
      "dataSources": {"primary": "ds_kpi_completed_today"},
      "options": {
        "majorColor": "#66ff66",
        "backgroundColor": "#000d00",
        "trendDisplay": "off"
      }
    },
